import unittest

from model_runtime.fast_handoff import fallback, validate


class FastHandoffTests(unittest.TestCase):
    def setUp(self):
        self.discovery = {
            "candidates": [
                {
                    "path": "nav/settings_benutzer.php",
                    "score": 80,
                    "pattern_counts": {"benutzer_liste": 2, "empty_state": 1},
                    "snippets": [{"snippet": "10: $benutzer_liste = benutzer_array();"}],
                },
                {
                    "path": "inc/funktionen_benutzer.php",
                    "score": 60,
                    "pattern_counts": {"benutzer_array": 1},
                    "snippets": [{"snippet": "20: function benutzer_array() {"}],
                },
                {
                    "path": "api/benutzer.php",
                    "score": 8,
                    "pattern_counts": {},
                    "snippets": [],
                },
            ]
        }

    def test_fallback_uses_only_evidence_candidates(self):
        handoff = fallback(self.discovery)
        validate(handoff, self.discovery)
        self.assertIn("nav/settings_benutzer.php", handoff["target_paths"])
        self.assertIn("inc/funktionen_benutzer.php", handoff["target_paths"])
        self.assertNotIn("wiki.php", handoff["target_paths"])

    def test_validate_rejects_invented_path(self):
        handoff = fallback(self.discovery)
        handoff["target_paths"].append("wiki.php")
        with self.assertRaises(ValueError):
            validate(handoff, self.discovery)


if __name__ == "__main__":
    unittest.main()
